    private static TreeMap<Integer,String> parseHls(String manifest,String url){TreeMap<Integer,String> out=new TreeMap<>();if(manifest==null||!manifest.trim().startsWith("#EXTM3U"))return out;String[] lines=manifest.split("\\r?\\n");int height=0;for(String line:lines){String l=line.trim();if(l.startsWith("#EXT-X-STREAM-INF")){Matcher m=Pattern.compile("RESOLUTION=\\d+x(\\d+)").matcher(l);height=m.find()?Integer.parseInt(m.group(1)):0;}else if(!l.isEmpty()&&!l.startsWith("#")&&height>0){out.put(height,absolute(url,l));height=0;}}return clean(out);}
