    private static String normalizeCvh(String value,String failover){String safe=ApiRepository.safeUrl(value);if(safe.isEmpty()||failover==null||failover.isEmpty())return safe;try{URL u=new URL(safe);if(!u.getProtocol().equalsIgnoreCase("https")||!u.getHost().matches("\\d{1,3}(?:\\.\\d{1,3}){3}"))return safe;return new URL(u.getProtocol(),failover,u.getPort(),u.getFile()).toString();}catch(Exception e){return safe;}}
