    private static String rutubeId(String text){Matcher p=Pattern.compile("(?i)(?:video|play/embed)/([a-f0-9]{32}|\\d{5,12})").matcher(text==null?"":text);if(p.find())return p.group(1);Matcher any=Pattern.compile("(?i)\\b([a-f0-9]{32})\\b").matcher(text==null?"":text);return any.find()?any.group(1):"";}
    private static TreeMap<Integer,String> zedfilm(ApiRepository api,String url)throws Exception{String page=normalizePayload(api.request(url,"GET",null,false,headers("https://hlamer.ru","https://yani.tv/")));TreeMap<Integer,String> out=new TreeMap<>();String encoded=find(page,"video_Init\\(\\s*[\\\"']([^\\\"']+)[\\\"']");if(!encoded.isEmpty())try{JSONObject json=new JSONObject(new String(Base64.decode(encoded,Base64.DEFAULT),StandardCharsets.UTF_8));for(String key:new String[]{"url","url2","hls","dash","src","file","source"})addStream(api,out,url,json.optString(key),url,0);Iterator<String> keys=json.keys();while(keys.hasNext()){String key=keys.next();Object value=json.opt(key);String lower=key.toLowerCase(Locale.ROOT);if(value instanceof String&&(lower.contains("url")||lower.contains("hls")||lower.contains("dash")||lower.contains("file")))addStream(api,out,url,(String)value,url,0);}}catch(Exception ignored){}collectStreams(api,out,url,page,url);if(out.isEmpty())return scan(api,url);return clean(out);}
    private static TreeMap<Integer,String> aniboom(ApiRepository api,String url)throws Exception{String page=api.request(url,"GET",null,false,headers(origin(url),"https://yani.tv/"));String dash=find(page,"&quot;dash&quot;:&quot;\\{\\\\&quot;src\\\\&quot;:\\\\&quot;(https[^;]+?\\.mpd)");if(dash.isEmpty())dash=find(page,"\\\"dash\\\"\\s*:\\s*\\\"(https[^\\\"]+?\\.mpd)\\\"");dash=dash.replace("\\\\\\/","/").replace("\\/","/");String safe=ApiRepository.safeUrl(dash);if(safe.isEmpty())throw new IOException("Aniboom не вернул видео");TreeMap<Integer,String> out=dash(api,safe);if(out.isEmpty())out.put(0,safe);return clean(out);}

    private static TreeMap<Integer,String> animetkaPlaylist(ApiRepository api,String url)throws Exception{String json=api.request(url,"GET",null,false,headers("https://animetka.com","https://animetka.com/"));JSONObject root=new JSONObject(json);TreeMap<Integer,String> out=new TreeMap<>();int want=queryInt(url,"episode",0);JSONArray list=root.optJSONArray("list");for(int i=0;list!=null&&i<list.length();i++){JSONObject item=list.optJSONObject(i);if(item==null)continue;double n=animetkaListNumber(item,i+1);if(want>0&&list.length()>1&&Math.abs(n-want)>0.001)continue;String file=normalizePayload(item.optString("file",""));Matcher m=Pattern.compile("[[]([0-9]{3,4})]([^,]+)").matcher(file);while(m.find()){int q=parseInt(m.group(1));String stream=absolute("https://animetka.com/",m.group(2));if(!stream.isEmpty())addStream(api,out,"https://animetka.com/",stream,url,q);}if(out.isEmpty()){Matcher raw=Pattern.compile("([^,]+?(?:[.]m3u8|[.]mpd|[.]mp4)[^,]*)",Pattern.CASE_INSENSITIVE).matcher(file);while(raw.find())addStream(api,out,"https://animetka.com/",raw.group(1),url,quality(raw.group(1)));}}if(out.isEmpty()){String link=ApiRepository.embed(root.optString("link",""));if(!link.isEmpty())try{return resolve(api,link);}catch(Exception ignored){}}return clean(out);}
    private static int queryInt(String url,String key,int fallback){try{String v=Uri.parse(url).getQueryParameter(key);return v==null||v.isEmpty()?fallback:Integer.parseInt(v.replaceAll("[^0-9]",""));}catch(Exception e){return fallback;}}
    private static double numberIn(String text,double fallback){Matcher m=Pattern.compile("[0-9]+(?:[.][0-9]+)?").matcher(text==null?"":text);try{return m.find()?Double.parseDouble(m.group()):fallback;}catch(Exception e){return fallback;}}
    private static double animetkaListNumber(JSONObject item,int fallback){String id=item.optString("id","");Matcher s=Pattern.compile("s([0-9]+(?:[.][0-9]+)?)",Pattern.CASE_INSENSITIVE).matcher(id);if(s.find())try{return Double.parseDouble(s.group(1));}catch(Exception ignored){}return numberIn(item.optString("title",""),fallback);}

    private static TreeMap<Integer,String> anilib(String url)throws Exception{String safe=ApiRepository.safeUrl(url);TreeMap<Integer,String> out=new TreeMap<>();if(!safe.isEmpty())out.put(quality(safe),safe);return clean(out);}
    private static void collectStreams(ApiRepository api,TreeMap<Integer,String> out,String base,String page,String referer){String text=normalizePayload(page);collectObjects(api,out,base,text,referer);Matcher field=Pattern.compile("(?:file|src|source|url|hls|dash)\\s*[:=]\\s*[\\\"']([^\\\"']+?(?:\\.m3u8|\\.mpd|\\.mp4|playlist|manifest|hls)[^\\\"']*)[\\\"']",Pattern.CASE_INSENSITIVE).matcher(text);while(field.find())addStream(api,out,base,field.group(1),referer,0);Matcher full=Pattern.compile("https?:\\\\?/\\\\?/[^\\\"'<>\\s]+?(?:\\.m3u8|\\.mpd|\\.mp4|playlist|manifest|hls)[^\\\"'<>\\s]*",Pattern.CASE_INSENSITIVE).matcher(text);while(full.find())addStream(api,out,base,full.group(),referer,0);Matcher proto=Pattern.compile("//[^\\\"'<>\\s]+?(?:\\.m3u8|\\.mpd|\\.mp4|playlist|manifest|hls)[^\\\"'<>\\s]*",Pattern.CASE_INSENSITIVE).matcher(text);while(proto.find())addStream(api,out,base,proto.group(),referer,0);}
    private static void collectObjects(ApiRepository api,TreeMap<Integer,String> out,String base,String text,String referer){Matcher obj=Pattern.compile("\\{[^{}]{0,1200}(?:file|src|source|url|hls|dash)[^{}]{0,1200}\\}",Pattern.CASE_INSENSITIVE).matcher(text);while(obj.find()){String row=obj.group();String link=first(find(row,"(?:file|src|source|url|hls|dash)\\s*[:=]\\s*[\\\"']([^\\\"']+?(?:\\.m3u8|\\.mpd|\\.mp4|playlist|manifest|hls)[^\\\"']*)[\\\"']"),find(row,"[\\\"']([^\\\"']+?(?:\\.m3u8|\\.mpd|\\.mp4|playlist|manifest|hls)[^\\\"']*)[\\\"']"));String q=first(find(row,"(?:quality|label|height|res)\\s*[:=]\\s*[\\\"']?([1-9][0-9]{2,3})p?"),find(row,"([1-9][0-9]{2,3})p"));addStream(api,out,base,link,referer,parseInt(q));}}
    private static void addStream(ApiRepository api,TreeMap<Integer,String> out,String base,String raw,String referer,int forcedQuality){String safe=absolute(base,normalizePayload(raw));if(!streamLike(safe))return;try{TreeMap<Integer,String> found=directWithReferer(api,safe,referer);if(found.isEmpty())found=probeUrl(safe,referer);if(found.isEmpty())out.put(forcedQuality>0?forcedQuality:quality(safe),safe);else for(Map.Entry<Integer,String> e:found.entrySet())if(!out.containsValue(e.getValue()))out.put(e.getKey()>0?e.getKey():(forcedQuality>0?forcedQuality:quality(e.getValue())),e.getValue());}catch(Exception e){out.put(forcedQuality>0?forcedQuality:quality(safe),safe);}}
    private static boolean streamLike(String url){String l=url==null?"":url.toLowerCase(Locale.ROOT);if(l.isEmpty()||l.contains("doubleclick")||l.contains("/ads/")||l.contains("yandex")||l.contains("adfox")||l.contains("ima"))return false;return l.contains(".m3u8")||l.contains(".mpd")||l.contains(".mp4")||l.contains(".mkv")||l.contains(".webm")||l.contains("playlist")||l.contains("manifest")||l.contains("/hls/");}
    private static String normalizePayload(String s){return s==null?"":s.replace("\\\\/","/").replace("\\/","/").replace("&amp;","&").replace("\\u0026","&").trim();}
    private static TreeMap<Integer,String> scan(ApiRepository api,String url)throws Exception{String page=api.request(url,"GET",null,false,headers(origin(url),"https://yani.tv/"));TreeMap<Integer,String> direct=new TreeMap<>();collectStreams(api,direct,url,page,url);if(!direct.isEmpty())return clean(direct);for(String frame:frames(url,page)){if(frame.equals(url))continue;try{TreeMap<Integer,String> out=resolve(api,frame);if(!out.isEmpty())return clean(out);}catch(Exception ignored){}}ArrayList<String> found=new ArrayList<>();Matcher f=Pattern.compile("(?:file|src|hls|dash|url)\\s*[:=]\\s*[\"']([^\"']+?(?:\\.m3u8|\\.mpd|\\.mp4|playlist|manifest|hls)[^\"']*)[\"']",Pattern.CASE_INSENSITIVE).matcher(page);while(f.find())found.add(f.group(1));Matcher u=Pattern.compile("https?:\\\\?/\\\\?/[^\"'<>\\s]+?(?:\\.m3u8|\\.mpd|\\.mp4|playlist|manifest|hls)[^\"'<>\\s]*",Pattern.CASE_INSENSITIVE).matcher(page);while(u.find())found.add(u.group());for(String s:found){String safe=absolute(url,s.replace("\\/","/"));if(safe.isEmpty())continue;try{TreeMap<Integer,String> out=direct(api,safe);if(out.isEmpty())out=probeUrl(safe,url);if(!out.isEmpty())return out;}catch(Exception ignored){}}throw new IOException("Просмотр не открыл подходящий вариант");}
    private static ArrayList<String> frames(String base,String page){LinkedHashSet<String> out=new LinkedHashSet<>();String text=normalizePayload(page);Matcher tag=Pattern.compile("<(?:iframe|embed)[^>]+(?:src|data-src|data-url)=[\"']([^\"']+)[\"']",Pattern.CASE_INSENSITIVE).matcher(text);while(tag.find())addFrame(out,base,tag.group(1));Matcher js=Pattern.compile("(?:iframe|player|embed|src)\\s*[:=]\\s*[\"'](https?:[^\"']+|//[^\"']+)[\"']",Pattern.CASE_INSENSITIVE).matcher(text);while(js.find())addFrame(out,base,js.group(1));return new ArrayList<>(out);}
    private static void addFrame(LinkedHashSet<String> out,String base,String raw){String safe=absolute(base,normalizePayload(raw));if(safe.isEmpty()||streamLike(safe))return;String h=host(safe),p=path(safe).toLowerCase(Locale.ROOT);if(h.contains("doubleclick")||h.contains("adfox")||h.contains("yandex")||h.contains("google")||h.contains("facebook"))return;boolean likely=p.contains("player")||p.contains("embed")||p.contains("iframe")||p.contains("watch")||p.contains("video");if(!likely){for(String kw:"kodik,aniqit,yani,cdnvideohub,aksor,sibnet,vk,rutube,aniboom".split(",")){if(h.contains(kw)){likely=true;break;}}}if(likely&&out.size()<8)out.add(safe);}
    private static TreeMap<Integer,String> probeUrl(String url,String referer){TreeMap<Integer,String> out=new TreeMap<>();String safe=ApiRepository.safeUrl(url);if(safe.isEmpty())return out;try{TaskQueue.check();HashMap<String,String> h=new HashMap<>();if(referer!=null&&!referer.isEmpty())h.put("Referer",referer);h.put("Range","bytes=0-8191");byte[] data=Net.bytes(safe,h,"video/*,application/vnd.apple.mpegurl,application/dash+xml,*/*;q=0.5",CHROME,"",2200,3200,8192);String head=data.length>0?new String(data,0,Math.min(data.length,8192),StandardCharsets.ISO_8859_1):"";boolean ok=head.startsWith("#EXTM3U")||head.contains("<MPD")||head.contains("ftyp");if(ok)out.put(quality(safe),safe);}catch(Exception ignored){}return clean(out);}
    private static TreeMap<Integer,String> clean(TreeMap<Integer,String> input){TreeMap<Integer,String> out=new TreeMap<>();for(Map.Entry<Integer,String> e:input.entrySet()){String s=ApiRepository.safeUrl(e.getValue());if(!s.isEmpty())out.put(e.getKey()==null?0:e.getKey(),s);}return out;}
    private static HashMap<String,String> headers(String origin,String referer){HashMap<String,String> h=new HashMap<>();h.put("Origin",origin);h.put("Referer",referer);h.put("Accept-Language","ru-RU,ru;q=0.9,en;q=0.5");h.put("User-Agent",CHROME);return h;}
    private static String origin(String url){try{Uri u=Uri.parse(url);return u.getScheme()+"://"+u.getHost();}catch(Exception e){return "https://yani.tv";}}
    private static String absolute(String base,String value){try{if(value==null||value.trim().isEmpty())return "";value=value.trim().replace("&amp;","&").replace("\\/","/");if(value.startsWith("//"))value="https:"+value;return ApiRepository.safeUrl(new URL(new URL(base),value).toString());}catch(Exception e){return "";}}
    private static String find(String input,String regex){Matcher m=Pattern.compile(regex,Pattern.CASE_INSENSITIVE|Pattern.DOTALL).matcher(input);return m.find()?unescape(m.group(1)):"";}
    private static String first(String a,String b){return a!=null&&!a.isEmpty()?a:b==null?"":b;}
    private static int parseInt(String value){try{return Integer.parseInt(value==null?"0":value.replaceAll("\\D+",""));}catch(Exception e){return 0;}}
    private static int quality(String url){Matcher m=Pattern.compile("(?:^|[^0-9])([1-9][0-9]{2,3})p?(?:[^0-9]|$)").matcher(url);int q=0;while(m.find()){try{int v=Integer.parseInt(m.group(1));if(v>=240&&v<=4320)q=v;}catch(Exception ignored){}}return q;}
    private static String decode(String src)throws Exception{if(src==null||src.isEmpty())return "";if(src.contains("//")||src.startsWith("http"))return fixProtocol(src);String caesar=caesar(src);int mod=caesar.length()%4;if(mod!=0)caesar=caesar+"====".substring(mod);return new String(Base64.decode(caesar,Base64.DEFAULT),StandardCharsets.UTF_8);}
    private static String caesar(String input){StringBuilder out=new StringBuilder();for(int i=0;i<input.length();i++){char ch=input.charAt(i);if(ch>='a'&&ch<='z')out.append((char)((ch-'a'+SHIFT)%26+'a'));else if(ch>='A'&&ch<='Z')out.append((char)((ch-'A'+SHIFT)%26+'A'));else out.append(ch);}return out.toString();}
    private static String fixProtocol(String s){if(s==null)return "";s=s.trim().replace("\\/","/").replace("&amp;","&");return s.startsWith("//")?"https:"+s:s;}
    private static String endpointPath(String script){Matcher m=Pattern.compile("atob\\(\"([A-Za-z0-9+/=]+)\"\\)").matcher(script);while(m.find())try{String decoded=new String(Base64.decode(m.group(1),Base64.DEFAULT),StandardCharsets.UTF_8);if(decoded.startsWith("/")&&!decoded.startsWith("//")&&decoded.length()<=16)return decoded;}catch(Exception ignored){}return "";}
    private static void add(StringBuilder body,String key,String value,boolean raw){if(body.length()>0)body.append('&');body.append(enc(key)).append('=').append(raw?value:enc(value));}
    private static boolean looksEncoded(String s){return s!=null&&s.matches(".*%[0-9A-Fa-f]{2}.*");}
    private static String unescape(String s){return s==null?"":s.replace("&quot;","\"").replace("&#34;","\"").replace("&#039;","'").replace("&amp;","&").replace("\\/","/");}
    private static String enc(String s){try{return URLEncoder.encode(s==null?"":s,"UTF-8");}catch(Exception e){return "";}}
    private static final class Page {String text="",cookies="";}
    private static Page fetch(String url,String referer)throws Exception{String safe=ApiRepository.safeUrl(url);if(safe.isEmpty())throw new IOException("Недопустимый адрес");TaskQueue.check();try{Net.Page loaded=Net.page(safe,referer,CHROME,"text/html,application/xhtml+xml,application/json,*/*;q=0.8",4500,6500,12*1024*1024);Page p=new Page();p.text=loaded.text;p.cookies=loaded.cookies;return p;}catch(Net.HttpCode e){throw new IOException("Просмотр не ответил");}}

    private static String postJson(String url,String body,String referer,String cookies)throws Exception{HashMap<String,String> h=headers(origin(url),referer);h.put("Accept","application/json, text/javascript, */*; q=0.01");h.put("X-Requested-With","XMLHttpRequest");if(cookies!=null&&!cookies.isEmpty())h.put("Cookie",cookies);String safe=ApiRepository.safeUrl(url);if(safe.isEmpty())throw new IOException("Недопустимый адрес");TaskQueue.check();try{return Net.text(safe,"POST",body,false,h,null,CHROME,4500,6500,12*1024*1024);}catch(Net.HttpCode e){throw new IOException("Просмотр не ответил");}}
    private static String post(String url,String body,String referer,String cookies)throws Exception{HashMap<String,String> h=headers(origin(url),referer);h.put("Accept","application/json, text/javascript, */*; q=0.01");h.put("X-Requested-With","XMLHttpRequest");if(cookies!=null&&!cookies.isEmpty())h.put("Cookie",cookies);String safe=ApiRepository.safeUrl(url);if(safe.isEmpty())throw new IOException("Недопустимый адрес");TaskQueue.check();try{return Net.text(safe,"POST",body,true,h,null,CHROME,4500,6500,12*1024*1024);}catch(Net.HttpCode e){throw new IOException("Просмотр не ответил");}}
